INSERT INTO recipes (name, country, continent, is_african, category, slug, summary, history, difficulty, prep_time, cook_time, servings, tags, image_url, ingredients, steps) VALUES

-- KENYA
('Kenyan Chai', 'Kenya', 'Africa', true, 'Drinks', 'kenyan-chai',
'Rich, creamy spiced tea simmered with whole milk, ginger, and cardamom - Kenya''s beloved daily ritual.',
'Chai was introduced to Kenya by Indian railway workers in the early 1900s. Kenyans adapted it with local preferences, creating a uniquely strong, milky version that is now integral to daily life.',
'Easy', 5, 10, 4, ARRAY['drinks', 'kenyan', 'tea', 'spiced', 'daily'],
'https://images.unsplash.com/photo-1571934811356-5cc061b6821f?w=800&auto=format&fit=crop',
'[{"item":"Black tea leaves (Kenya CTC)","quantity":"3 tbsp"},{"item":"Whole milk","quantity":"2 cups"},{"item":"Water","quantity":"2 cups"},{"item":"Fresh ginger","quantity":"1 inch","note":"crushed"},{"item":"Cardamom pods","quantity":"3","note":"crushed"},{"item":"Sugar","quantity":"to taste"},{"item":"Cinnamon stick","quantity":"1","note":"optional"}]',
'[{"step":1,"instruction":"Add water, crushed ginger, and cardamom to a pot. Bring to a boil."},{"step":2,"instruction":"Add tea leaves and boil for 2 minutes until dark."},{"step":3,"instruction":"Add milk and sugar. Simmer for 5-7 minutes, letting it rise and fall 2-3 times."},{"step":4,"instruction":"Strain into cups. Serve hot. Kenyan chai should be strong and creamy."}]'),

('Uji', 'Kenya', 'Africa', true, 'Breakfast', 'uji-kenya',
'Smooth fermented millet porridge sweetened with sugar - Kenya''s traditional breakfast that nourishes all ages.',
'Uji has been a morning staple across East Africa for generations. Made from fermented flour, it provides sustained energy and is given to children and nursing mothers for its nutritional benefits.',
'Easy', 10, 15, 4, ARRAY['breakfast', 'kenyan', 'porridge', 'millet', 'fermented'],
'https://images.unsplash.com/photo-1517673400267-0251440c45dc?w=800&auto=format&fit=crop',
'[{"item":"Millet flour","quantity":"1 cup"},{"item":"Sorghum flour","quantity":"1/2 cup"},{"item":"Water","quantity":"4 cups"},{"item":"Sugar","quantity":"to taste"},{"item":"Lemon juice","quantity":"1 tbsp","note":"for fermentation"}]',
'[{"step":1,"instruction":"Mix flours with 1 cup cold water and lemon juice. Let ferment 12-24 hours."},{"step":2,"instruction":"Boil remaining water. Stir fermented paste into boiling water gradually."},{"step":3,"instruction":"Cook on low heat 10 minutes, stirring constantly until smooth and thick."},{"step":4,"instruction":"Add sugar. Serve warm in cups or bowls."}]'),

('Nyama Choma', 'Kenya', 'Africa', true, 'Dinner', 'nyama-choma-kenya',
'Kenyan charcoal-grilled goat meat seasoned simply with salt and lime - the ultimate dinner gathering dish.',
'Nyama Choma (roasted meat) is Kenya''s most celebrated social food. Gatherings revolve around the grill, and it is said that no Kenyan celebration is complete without it.',
'Easy', 15, 45, 6, ARRAY['dinner', 'kenyan', 'grilled', 'goat', 'social'],
'https://images.unsplash.com/photo-1529692236671-f1f6cf9683ba?w=800&auto=format&fit=crop',
'[{"item":"Goat ribs or leg","quantity":"2 kg"},{"item":"Salt","quantity":"2 tbsp"},{"item":"Lime","quantity":"3","note":"halved"},{"item":"Ugali","quantity":"for serving"},{"item":"Kachumbari (tomato-onion salad)","quantity":"for serving"}]',
'[{"step":1,"instruction":"Season goat meat generously with salt only - the Kenyan way is simple seasoning."},{"step":2,"instruction":"Grill over hot charcoal, turning occasionally, for 30-45 minutes until charred outside and juicy inside."},{"step":3,"instruction":"Squeeze lime juice over the meat just before serving."},{"step":4,"instruction":"Cut into pieces and serve with ugali and kachumbari salad."}]'),

('Sukuma Wiki', 'Kenya', 'Africa', true, 'Lunch', 'sukuma-wiki-kenya',
'Sautéed collard greens with tomatoes and onions - Kenya''s everyday affordable lunch served with ugali.',
'Sukuma Wiki literally means "push the week" in Swahili, reflecting its role as an affordable, nutritious dish that stretches the budget through the week.',
'Easy', 10, 15, 4, ARRAY['lunch', 'kenyan', 'greens', 'vegetarian', 'affordable'],
'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=800&auto=format&fit=crop',
'[{"item":"Collard greens (sukuma wiki)","quantity":"1 large bunch","note":"finely shredded"},{"item":"Tomatoes","quantity":"3","note":"diced"},{"item":"Onion","quantity":"1","note":"sliced"},{"item":"Vegetable oil","quantity":"2 tbsp"},{"item":"Salt","quantity":"to taste"},{"item":"Ugali","quantity":"for serving"}]',
'[{"step":1,"instruction":"Heat oil and sauté onions until golden."},{"step":2,"instruction":"Add tomatoes and cook until soft, about 5 minutes."},{"step":3,"instruction":"Add shredded collard greens and salt. Stir well."},{"step":4,"instruction":"Cook for 5-7 minutes until greens are tender but still bright green. Do not overcook."},{"step":5,"instruction":"Serve immediately with ugali."}]'),

('Madafu', 'Kenya', 'Africa', true, 'Drinks', 'madafu-kenya',
'Fresh young coconut water served straight from the shell - the refreshing coastal Kenyan drink.',
'Madafu is a symbol of the Kenyan coast, sold by vendors who skillfully chop open green coconuts with machetes. It is both a refreshment and a cultural marker of Mombasa and the Swahili coast.',
'Easy', 5, 0, 1, ARRAY['drinks', 'kenyan', 'coconut', 'natural', 'coastal'],
'https://images.unsplash.com/photo-1513558161293-cdaf765ed2fd?w=800&auto=format&fit=crop',
'[{"item":"Young green coconut","quantity":"1"},{"item":"Straw","quantity":"1"},{"item":"Lime","quantity":"optional, for squeezing"}]',
'[{"step":1,"instruction":"Select a young green coconut - it should feel heavy with water."},{"step":2,"instruction":"Using a sharp machete, cut the top off the coconut to create an opening."},{"step":3,"instruction":"Insert a straw and drink the sweet, naturally sterile water."},{"step":4,"instruction":"After drinking, ask the vendor to split it open so you can eat the soft jelly-like flesh inside."}]'),

-- TANZANIA
('Vitumbua', 'Tanzania', 'Africa', true, 'Breakfast', 'vitumbua-tanzania',
'Crispy coconut rice pancakes, sweetened and spiced with cardamom - a beloved Swahili breakfast from Tanzania.',
'Vitumbua are a treasured Swahili breakfast food cooked in a special cast-iron pan called kikaango. They are sold at every morning market along the Tanzanian coast.',
'Easy', 20, 15, 6, ARRAY['breakfast', 'tanzanian', 'coconut', 'rice', 'swahili'],
'https://images.unsplash.com/photo-1567364816519-cbc9c4a0a736?w=800&auto=format&fit=crop',
'[{"item":"Rice flour","quantity":"2 cups"},{"item":"Coconut milk","quantity":"1.5 cups"},{"item":"Sugar","quantity":"1/3 cup"},{"item":"Yeast","quantity":"1 tsp"},{"item":"Cardamom","quantity":"1/2 tsp","note":"ground"},{"item":"Salt","quantity":"pinch"},{"item":"Coconut oil","quantity":"for cooking"}]',
'[{"step":1,"instruction":"Mix rice flour, sugar, yeast, cardamom, and salt. Add warm coconut milk."},{"step":2,"instruction":"Stir until smooth. Cover and let rise for 2 hours until bubbly."},{"step":3,"instruction":"Heat oiled vitumbua pan (or mini pancake pan) over medium heat."},{"step":4,"instruction":"Pour batter into each mold. Cook until golden underneath, flip and cook other side."},{"step":5,"instruction":"Serve warm for breakfast with chai tea."}]'),

('Pilau', 'Tanzania', 'Africa', true, 'Lunch', 'pilau-tanzania',
'Aromatic spiced rice with tender beef, cooked in a rich blend of pilau masala - Tanzania''s festive lunch dish.',
'Pilau reflects the Arab and Indian influences on Swahili cuisine. It is the centerpiece of celebrations, weddings, and Friday lunches after mosque.',
'Medium', 20, 45, 6, ARRAY['lunch', 'tanzanian', 'rice', 'spiced', 'beef'],
'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=800&auto=format&fit=crop',
'[{"item":"Basmati rice","quantity":"3 cups"},{"item":"Beef","quantity":"500g","note":"cubed"},{"item":"Onions","quantity":"3 large","note":"thinly sliced"},{"item":"Pilau masala","quantity":"2 tbsp"},{"item":"Garlic","quantity":"4 cloves","note":"minced"},{"item":"Ginger","quantity":"1 inch","note":"grated"},{"item":"Whole cumin seeds","quantity":"1 tsp"},{"item":"Cardamom pods","quantity":"4"},{"item":"Cinnamon stick","quantity":"1"},{"item":"Beef broth","quantity":"4 cups"},{"item":"Vegetable oil","quantity":"1/4 cup"},{"item":"Salt","quantity":"to taste"}]',
'[{"step":1,"instruction":"Caramelize onions in oil until deep brown. Remove half for garnish."},{"step":2,"instruction":"Add whole spices (cumin, cardamom, cinnamon) to remaining onions. Fry 1 minute."},{"step":3,"instruction":"Add beef, garlic, ginger. Brown on all sides."},{"step":4,"instruction":"Add pilau masala and salt. Stir well. Add broth and simmer until meat is tender."},{"step":5,"instruction":"Add washed rice. Cook covered on low heat for 20 minutes until rice absorbs all liquid."},{"step":6,"instruction":"Fluff with fork. Top with caramelized onions. Serve with kachumbari."}]'),

('Mchuzi wa Samaki', 'Tanzania', 'Africa', true, 'Dinner', 'mchuzi-wa-samaki-tanzania',
'Tanzanian coconut fish curry with turmeric, tamarind, and fresh vegetables - a coastal dinner specialty.',
'This coconut fish curry represents the culinary soul of Zanzibar and the Tanzanian coast, where the spice trade created a cuisine rich in aromatic complexity.',
'Medium', 15, 30, 4, ARRAY['dinner', 'tanzanian', 'fish', 'coconut', 'curry'],
'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=800&auto=format&fit=crop',
'[{"item":"White fish fillets","quantity":"4"},{"item":"Coconut milk","quantity":"400ml"},{"item":"Tomatoes","quantity":"3","note":"diced"},{"item":"Onion","quantity":"1","note":"chopped"},{"item":"Garlic","quantity":"3 cloves"},{"item":"Turmeric","quantity":"1 tsp"},{"item":"Cumin","quantity":"1 tsp"},{"item":"Tamarind paste","quantity":"1 tbsp"},{"item":"Green bell pepper","quantity":"1","note":"sliced"},{"item":"Chili","quantity":"1"},{"item":"Coriander","quantity":"for garnish"},{"item":"Salt","quantity":"to taste"}]',
'[{"step":1,"instruction":"Season fish with turmeric and salt. Set aside."},{"step":2,"instruction":"Sauté onion, garlic, and chili. Add cumin and cook 1 minute."},{"step":3,"instruction":"Add tomatoes and cook 5 minutes. Add bell pepper."},{"step":4,"instruction":"Pour in coconut milk and tamarind paste. Simmer 10 minutes."},{"step":5,"instruction":"Gently add fish fillets. Cover and cook 10-12 minutes until fish flakes."},{"step":6,"instruction":"Garnish with coriander. Serve with rice or chapati."}]'),

('Tangawizi', 'Tanzania', 'Africa', true, 'Drinks', 'tangawizi-tanzania',
'Intense Tanzanian fresh ginger juice with lime - a fiery, refreshing drink sold across the country.',
'Tangawizi (ginger) juice is a beloved Tanzanian refreshment, known for its health benefits and intense flavor. It is sold at street stalls and restaurants throughout the country.',
'Easy', 10, 0, 4, ARRAY['drinks', 'tanzanian', 'ginger', 'lime', 'healthy'],
'https://images.unsplash.com/photo-1513558161293-cdaf765ed2fd?w=800&auto=format&fit=crop',
'[{"item":"Fresh ginger","quantity":"300g","note":"peeled"},{"item":"Limes","quantity":"3","note":"juiced"},{"item":"Sugar","quantity":"1/2 cup"},{"item":"Water","quantity":"1 liter"},{"item":"Ice","quantity":"for serving"}]',
'[{"step":1,"instruction":"Blend fresh ginger with 2 cups water until very smooth."},{"step":2,"instruction":"Strain through fine mesh, pressing out all juice."},{"step":3,"instruction":"Add remaining water, lime juice, and sugar. Stir until dissolved."},{"step":4,"instruction":"Serve over ice. Adjust sweetness and ginger intensity to taste."}]'),

-- ETHIOPIA
('Genfo', 'Ethiopia', 'Africa', true, 'Breakfast', 'genfo-ethiopia',
'Ethiopian barley flour porridge shaped into a volcano with a well of spiced clarified butter and berbere - a traditional celebration breakfast.',
'Genfo is prepared for new mothers and at special occasions. The volcano shape with the butter well is symbolic, and eating it is a communal act of celebration.',
'Easy', 5, 15, 4, ARRAY['breakfast', 'ethiopian', 'barley', 'porridge', 'celebration'],
'https://images.unsplash.com/photo-1517673400267-0251440c45dc?w=800&auto=format&fit=crop',
'[{"item":"Barley flour","quantity":"2 cups"},{"item":"Water","quantity":"3 cups"},{"item":"Niter kibbeh (spiced butter)","quantity":"4 tbsp"},{"item":"Berbere spice","quantity":"2 tsp"},{"item":"Salt","quantity":"1/2 tsp"},{"item":"Yogurt","quantity":"for serving"}]',
'[{"step":1,"instruction":"Bring water and salt to a rolling boil."},{"step":2,"instruction":"Gradually add barley flour while stirring vigorously with a wooden spoon to prevent lumps."},{"step":3,"instruction":"Cook for 10 minutes, stirring constantly until very thick and dough-like."},{"step":4,"instruction":"Shape into a mound on a plate. Make a well in the center."},{"step":5,"instruction":"Fill the well with melted niter kibbeh and sprinkle berbere around the edges. Serve with yogurt."}]'),

('Kitfo', 'Ethiopia', 'Africa', true, 'Dinner', 'kitfo-ethiopia',
'Ethiopian hand-minced lean beef seasoned with mitmita spice and niter kibbeh - served raw or lightly cooked.',
'Kitfo is considered one of Ethiopia''s finest dishes, originating from the Gurage people. It represents the Ethiopian tradition of raw meat dishes and is a marker of celebration and prosperity.',
'Medium', 20, 5, 4, ARRAY['dinner', 'ethiopian', 'beef', 'raw', 'gurage'],
'https://images.unsplash.com/photo-1529692236671-f1f6cf9683ba?w=800&auto=format&fit=crop',
'[{"item":"Lean beef (tenderloin)","quantity":"500g","note":"very fresh"},{"item":"Niter kibbeh (spiced butter)","quantity":"3 tbsp","note":"melted"},{"item":"Mitmita spice","quantity":"2 tbsp"},{"item":"Cardamom","quantity":"1/4 tsp"},{"item":"Kocho (false banana bread)","quantity":"for serving"},{"item":"Ayib (Ethiopian cottage cheese)","quantity":"1/2 cup"},{"item":"Gomen (collard greens)","quantity":"1 cup","note":"cooked"}]',
'[{"step":1,"instruction":"Hand-mince the beef very finely using a sharp knife (do not use a grinder for authentic texture)."},{"step":2,"instruction":"In a warm pan, melt niter kibbeh. Add mitmita and cardamom."},{"step":3,"instruction":"Add minced beef to the warm (not hot) butter. Toss gently - for ''lebleb'' (lightly warmed) or serve raw."},{"step":4,"instruction":"Serve immediately on a plate with ayib and gomen on the side, with kocho or injera."}]'),

('Tej', 'Ethiopia', 'Africa', true, 'Drinks', 'tej-ethiopia',
'Ethiopian honey wine (mead) fermented with gesho leaves - a golden, sweet alcoholic beverage.',
'Tej is Ethiopia''s ancient honey wine, dating back thousands of years. It is served in distinctive flask-shaped glasses called berele and is central to Ethiopian celebrations and traditional bars (tej bet).',
'Medium', 30, 0, 8, ARRAY['drinks', 'ethiopian', 'honey', 'wine', 'traditional', 'alcoholic'],
'https://images.unsplash.com/photo-1513558161293-cdaf765ed2fd?w=800&auto=format&fit=crop',
'[{"item":"Raw honey","quantity":"1 kg"},{"item":"Water","quantity":"3 liters"},{"item":"Gesho leaves or powder","quantity":"1/2 cup"},{"item":"Berele glasses","quantity":"for serving"}]',
'[{"step":1,"instruction":"Dissolve honey in water in a large glass or plastic container."},{"step":2,"instruction":"Add gesho leaves (the bittering agent that also provides yeast)."},{"step":3,"instruction":"Cover loosely and let ferment at room temperature for 2-4 weeks, stirring occasionally."},{"step":4,"instruction":"Strain through a cloth when desired sweetness/alcohol level is reached."},{"step":5,"instruction":"Serve in traditional berele glasses. Tej ranges from very sweet to dry depending on fermentation time."}]'),

('Shiro Wot', 'Ethiopia', 'Africa', true, 'Lunch', 'shiro-wot-ethiopia',
'Silky Ethiopian ground chickpea stew seasoned with berbere and onions - the everyday comfort lunch.',
'Shiro is Ethiopia''s most commonly eaten dish, affordable and satisfying. During Orthodox fasting periods, it is the go-to vegan meal, demonstrating Ethiopian cuisine''s deep vegetarian tradition.',
'Easy', 10, 25, 4, ARRAY['lunch', 'ethiopian', 'chickpea', 'vegan', 'fasting'],
'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=800&auto=format&fit=crop',
'[{"item":"Shiro powder (roasted chickpea flour)","quantity":"1 cup"},{"item":"Onion","quantity":"2 large","note":"very finely diced"},{"item":"Garlic","quantity":"4 cloves","note":"minced"},{"item":"Tomato paste","quantity":"2 tbsp"},{"item":"Berbere spice","quantity":"1 tbsp"},{"item":"Vegetable oil","quantity":"3 tbsp"},{"item":"Water","quantity":"2.5 cups"},{"item":"Salt","quantity":"to taste"},{"item":"Injera","quantity":"for serving"}]',
'[{"step":1,"instruction":"Dry-cook finely diced onions in a pot until deep golden (no oil yet), about 10 minutes."},{"step":2,"instruction":"Add oil, garlic, tomato paste, and berbere. Cook 5 minutes."},{"step":3,"instruction":"Gradually add water while stirring. Bring to a simmer."},{"step":4,"instruction":"Whisk in shiro powder slowly to avoid lumps. Cook 10-15 minutes until thick and smooth."},{"step":5,"instruction":"Adjust salt and consistency. Serve over injera."}]'),

-- UGANDA
('Rolex', 'Uganda', 'Africa', true, 'Breakfast', 'rolex-uganda',
'Ugandan street food sensation - a thin chapati rolled around a spiced egg omelette with fresh vegetables.',
'The Rolex (from "Rolled Eggs") was invented by Ugandan street food vendors in the 2000s and quickly became the country''s most popular breakfast and snack. It even has its own festival.',
'Easy', 10, 10, 2, ARRAY['breakfast', 'ugandan', 'eggs', 'street-food', 'chapati'],
'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=800&auto=format&fit=crop',
'[{"item":"Chapati","quantity":"2"},{"item":"Eggs","quantity":"4"},{"item":"Tomato","quantity":"1","note":"diced"},{"item":"Onion","quantity":"1/2","note":"sliced"},{"item":"Cabbage","quantity":"1/2 cup","note":"shredded"},{"item":"Green pepper","quantity":"1","note":"sliced"},{"item":"Salt","quantity":"to taste"},{"item":"Vegetable oil","quantity":"for cooking"}]',
'[{"step":1,"instruction":"Beat eggs with salt. Add diced tomato, onion, cabbage, and green pepper."},{"step":2,"instruction":"Heat oil in a pan. Pour egg mixture to make a thin omelette."},{"step":3,"instruction":"When nearly set, place a chapati on top. Flip so chapati is on bottom."},{"step":4,"instruction":"Cook until egg is fully set. Roll tightly."},{"step":5,"instruction":"Wrap in paper. Serve immediately while hot."}]'),

('Luwombo', 'Uganda', 'Africa', true, 'Dinner', 'luwombo-uganda',
'Ugandan chicken or beef stew slow-steamed in banana leaves - a royal dinner dish from the Buganda kingdom.',
'Luwombo was created in 1887 by the personal chef of Kabaka Mwanga II of Buganda. It remains Uganda''s most prestigious dinner, served at weddings and official functions.',
'Hard', 30, 120, 6, ARRAY['dinner', 'ugandan', 'chicken', 'banana-leaf', 'royal'],
'https://images.unsplash.com/photo-1598103442097-8b74394b95c6?w=800&auto=format&fit=crop',
'[{"item":"Chicken","quantity":"1 whole","note":"cut into pieces"},{"item":"Banana leaves","quantity":"4 large"},{"item":"Peanut butter","quantity":"3 tbsp"},{"item":"Tomatoes","quantity":"3","note":"diced"},{"item":"Onions","quantity":"2","note":"sliced"},{"item":"Mushrooms","quantity":"1 cup","note":"sliced"},{"item":"Green pepper","quantity":"1","note":"chopped"},{"item":"Curry powder","quantity":"1 tsp"},{"item":"Salt","quantity":"to taste"}]',
'[{"step":1,"instruction":"Mix chicken with peanut butter, tomatoes, onions, mushrooms, green pepper, curry powder, and salt."},{"step":2,"instruction":"Soften banana leaves over a flame. Place on a flat surface."},{"step":3,"instruction":"Divide the chicken mixture onto the banana leaves."},{"step":4,"instruction":"Wrap tightly, securing with banana leaf strips or string."},{"step":5,"instruction":"Steam the parcels in a large pot for 1.5-2 hours."},{"step":6,"instruction":"Unwrap at the table. Serve with matoke (steamed green bananas) or rice."}]'),

('Bushera', 'Uganda', 'Africa', true, 'Drinks', 'bushera-uganda',
'Ugandan fermented millet and sorghum drink - thick, tangy, and naturally probiotic.',
'Bushera is a traditional drink of western Uganda, particularly popular among the Bakiga people. It is both a refreshment and a nutritional supplement, given to children and adults alike.',
'Easy', 30, 15, 6, ARRAY['drinks', 'ugandan', 'millet', 'fermented', 'probiotic'],
'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=800&auto=format&fit=crop',
'[{"item":"Millet flour","quantity":"1 cup"},{"item":"Sorghum flour","quantity":"1/2 cup"},{"item":"Water","quantity":"4 cups"},{"item":"Sugar","quantity":"to taste"},{"item":"Lemon","quantity":"1/2","note":"juiced for starter"}]',
'[{"step":1,"instruction":"Mix millet and sorghum flour with 1 cup cold water."},{"step":2,"instruction":"Boil 3 cups water. Gradually stir in the flour paste."},{"step":3,"instruction":"Cook for 10 minutes, stirring constantly. Let cool to room temperature."},{"step":4,"instruction":"Add lemon juice and cover. Let ferment 24-48 hours until tangy."},{"step":5,"instruction":"Stir well, add sugar. Serve cold. Consistency should be thick like a smoothie."}]'),

('Matoke', 'Uganda', 'Africa', true, 'Lunch', 'matoke-uganda',
'Steamed and mashed green bananas with a peanut and tomato sauce - Uganda''s beloved national lunch.',
'Matoke is so central to Ugandan identity that the word ''to eat'' in some Ugandan languages literally translates as ''to eat matoke.'' It is the country''s most consumed starch.',
'Easy', 15, 30, 4, ARRAY['lunch', 'ugandan', 'banana', 'peanut', 'national-dish'],
'https://images.unsplash.com/photo-1574484284002-952d92456975?w=800&auto=format&fit=crop',
'[{"item":"Green bananas (matoke)","quantity":"8","note":"peeled"},{"item":"Peanut butter","quantity":"2 tbsp"},{"item":"Tomatoes","quantity":"2","note":"diced"},{"item":"Onion","quantity":"1","note":"chopped"},{"item":"Garlic","quantity":"2 cloves"},{"item":"Salt","quantity":"to taste"},{"item":"Banana leaves","quantity":"for wrapping"}]',
'[{"step":1,"instruction":"Wrap peeled green bananas in banana leaves. Steam for 20 minutes until soft."},{"step":2,"instruction":"Mash the steamed bananas until smooth."},{"step":3,"instruction":"Sauté onion and garlic. Add tomatoes and cook until soft."},{"step":4,"instruction":"Add peanut butter and a little water to make a sauce. Season with salt."},{"step":5,"instruction":"Serve mashed matoke with the peanut-tomato sauce."}]'),

-- RWANDA
('Ikivuguto', 'Rwanda', 'Africa', true, 'Drinks', 'ikivuguto-rwanda',
'Rwandan traditional fermented milk drink - thick, tangy, and naturally cultured in a calabash.',
'Ikivuguto is deeply embedded in Rwandan culture, particularly among pastoralist communities. The traditional preparation in a calabash gourd imparts a unique smoky flavor.',
'Easy', 10, 0, 4, ARRAY['drinks', 'rwandan', 'fermented-milk', 'traditional', 'probiotic'],
'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=800&auto=format&fit=crop',
'[{"item":"Fresh whole milk","quantity":"1 liter"},{"item":"Existing ikivuguto culture","quantity":"2 tbsp","note":"or plain yogurt"},{"item":"Sugar","quantity":"optional"}]',
'[{"step":1,"instruction":"Warm fresh milk to lukewarm (not hot)."},{"step":2,"instruction":"Add the culture starter and stir gently."},{"step":3,"instruction":"Pour into a clean calabash or glass container. Cover loosely."},{"step":4,"instruction":"Let ferment at room temperature for 24-48 hours until thick and tangy."},{"step":5,"instruction":"Stir well before drinking. Serve at room temperature or slightly chilled."}]'),

('Isombe', 'Rwanda', 'Africa', true, 'Lunch', 'isombe-rwanda',
'Rwandan cassava leaves with eggplant, spinach, and peanut paste - a nutritious everyday lunch.',
'Isombe is a cornerstone of Rwandan home cooking, representing the country''s tradition of making flavorful, nutritious meals from leafy greens and legumes.',
'Easy', 20, 30, 4, ARRAY['lunch', 'rwandan', 'cassava-leaves', 'peanut', 'vegetarian'],
'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=800&auto=format&fit=crop',
'[{"item":"Cassava leaves","quantity":"500g","note":"ground"},{"item":"Eggplant","quantity":"1","note":"diced"},{"item":"Spinach","quantity":"1 cup"},{"item":"Peanut paste","quantity":"3 tbsp"},{"item":"Onion","quantity":"1","note":"chopped"},{"item":"Palm oil","quantity":"2 tbsp"},{"item":"Salt","quantity":"to taste"}]',
'[{"step":1,"instruction":"Boil ground cassava leaves for 20 minutes. Drain."},{"step":2,"instruction":"Sauté onion in palm oil. Add eggplant and cook until soft."},{"step":3,"instruction":"Add cassava leaves and spinach. Stir well."},{"step":4,"instruction":"Dissolve peanut paste in water and add to pot."},{"step":5,"instruction":"Simmer 10 minutes. Season and serve with rice."}]'),

('Ibihaza', 'Rwanda', 'Africa', true, 'Dinner', 'ibihaza-rwanda',
'Rwandan spiced pumpkin stew with onions and tomatoes - a comforting vegetarian dinner.',
'Ibihaza celebrates Rwanda''s abundant pumpkin harvest. The vegetable is versatile in Rwandan cooking, used in soups, stews, and even beverages.',
'Easy', 10, 25, 4, ARRAY['dinner', 'rwandan', 'pumpkin', 'vegetarian', 'stew'],
'https://images.unsplash.com/photo-1574484284002-952d92456975?w=800&auto=format&fit=crop',
'[{"item":"Pumpkin","quantity":"1 kg","note":"peeled and cubed"},{"item":"Tomatoes","quantity":"2","note":"diced"},{"item":"Onion","quantity":"1","note":"chopped"},{"item":"Garlic","quantity":"2 cloves"},{"item":"Vegetable oil","quantity":"2 tbsp"},{"item":"Salt","quantity":"to taste"},{"item":"Cinnamon","quantity":"pinch"}]',
'[{"step":1,"instruction":"Sauté onion and garlic in oil until fragrant."},{"step":2,"instruction":"Add tomatoes and cook until soft."},{"step":3,"instruction":"Add pumpkin cubes, salt, and cinnamon. Add 1 cup water."},{"step":4,"instruction":"Cover and cook 20 minutes until pumpkin is tender."},{"step":5,"instruction":"Mash lightly if desired. Serve with rice or bread."}]'),

-- SOMALIA
('Canjeero', 'Somalia', 'Africa', true, 'Breakfast', 'canjeero-somalia',
'Somali fermented pancake made from sorghum or wheat - spongy, tangy, and perfect for breakfast.',
'Canjeero (also called Laxoox) is the Somali equivalent of Ethiopian injera but with a lighter texture. It is the foundation of every Somali breakfast.',
'Easy', 480, 15, 4, ARRAY['breakfast', 'somali', 'fermented', 'flatbread', 'sorghum'],
'https://images.unsplash.com/photo-1567364816519-cbc9c4a0a736?w=800&auto=format&fit=crop',
'[{"item":"Self-rising flour","quantity":"2 cups"},{"item":"Cornmeal","quantity":"1/2 cup"},{"item":"Sugar","quantity":"2 tbsp"},{"item":"Yeast","quantity":"1 tsp"},{"item":"Warm water","quantity":"2.5 cups"},{"item":"Vegetable oil","quantity":"for cooking"}]',
'[{"step":1,"instruction":"Mix flour, cornmeal, sugar, and yeast with warm water until smooth."},{"step":2,"instruction":"Cover and ferment for 6-8 hours or overnight."},{"step":3,"instruction":"Heat a non-stick pan. Pour a thin layer of batter, swirling to cover."},{"step":4,"instruction":"Cook one side only until set and spongy with small holes on top."},{"step":5,"instruction":"Serve with butter and honey, or with suqaar (sautéed meat)."}]'),

('Bariis Iskukaris', 'Somalia', 'Africa', true, 'Lunch', 'bariis-iskukaris-somalia',
'Somali fragrant spiced rice with raisins, caramelized onions, and tender meat - a celebratory lunch dish.',
'Bariis Iskukaris is Somalia''s festive rice dish, influenced by Indian and Arab traders. It is the centerpiece of Somali weddings and Eid celebrations.',
'Medium', 20, 40, 6, ARRAY['lunch', 'somali', 'rice', 'spiced', 'festive'],
'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=800&auto=format&fit=crop',
'[{"item":"Basmati rice","quantity":"3 cups"},{"item":"Lamb or goat","quantity":"500g","note":"cubed"},{"item":"Onions","quantity":"2","note":"sliced"},{"item":"Xawaash spice mix","quantity":"2 tbsp"},{"item":"Cumin seeds","quantity":"1 tsp"},{"item":"Cardamom pods","quantity":"4"},{"item":"Cinnamon stick","quantity":"1"},{"item":"Raisins","quantity":"1/4 cup"},{"item":"Ghee","quantity":"3 tbsp"},{"item":"Salt","quantity":"to taste"},{"item":"Water","quantity":"4 cups"}]',
'[{"step":1,"instruction":"Caramelize onions in ghee until deep brown. Remove half for garnish."},{"step":2,"instruction":"Add meat and brown. Add whole spices and xawaash. Cook 5 minutes."},{"step":3,"instruction":"Add water and simmer until meat is tender, about 25 minutes."},{"step":4,"instruction":"Add washed rice and raisins. Cook covered on low heat for 20 minutes."},{"step":5,"instruction":"Fluff with fork. Top with caramelized onions. Serve with banana and salad."}]'),

('Shaah', 'Somalia', 'Africa', true, 'Drinks', 'shaah-somalia',
'Somali spiced tea with cardamom, cinnamon, and cloves - rich, aromatic, and served with plenty of sugar.',
'Shaah is the social glue of Somali culture. Offering tea to a guest is the first act of hospitality, and refusing it is considered impolite.',
'Easy', 5, 10, 4, ARRAY['drinks', 'somali', 'tea', 'spiced', 'cardamom'],
'https://images.unsplash.com/photo-1571934811356-5cc061b6821f?w=800&auto=format&fit=crop',
'[{"item":"Black tea leaves","quantity":"3 tbsp"},{"item":"Cardamom pods","quantity":"5","note":"crushed"},{"item":"Cinnamon stick","quantity":"1"},{"item":"Whole cloves","quantity":"3"},{"item":"Milk","quantity":"1.5 cups"},{"item":"Water","quantity":"1.5 cups"},{"item":"Sugar","quantity":"3 tbsp"}]',
'[{"step":1,"instruction":"Boil water with cardamom, cinnamon, and cloves for 3 minutes."},{"step":2,"instruction":"Add tea leaves and boil 2 more minutes."},{"step":3,"instruction":"Add milk and sugar. Let simmer and rise 3 times."},{"step":4,"instruction":"Strain into small cups. Serve hot with Somali cookies."}]'),

-- SUDAN
('Kisra', 'Sudan', 'Africa', true, 'Breakfast', 'kisra-sudan',
'Sudanese thin fermented sorghum flatbread - tangy, flexible, and the foundation of every Sudanese meal.',
'Kisra is Sudan''s staple bread, made from fermented sorghum or millet dough. The fermentation process, lasting 2-3 days, gives it a sourdough-like tang.',
'Medium', 2880, 15, 6, ARRAY['breakfast', 'sudanese', 'sorghum', 'fermented', 'flatbread'],
'https://images.unsplash.com/photo-1567364816519-cbc9c4a0a736?w=800&auto=format&fit=crop',
'[{"item":"Sorghum flour","quantity":"2 cups"},{"item":"Water","quantity":"3 cups"},{"item":"Salt","quantity":"1/2 tsp"},{"item":"Oil","quantity":"for cooking"}]',
'[{"step":1,"instruction":"Mix sorghum flour with water to form a thin batter. Cover and ferment 2-3 days."},{"step":2,"instruction":"The batter should be bubbly and smell slightly sour. Add salt."},{"step":3,"instruction":"Heat a large flat pan or griddle. Lightly oil."},{"step":4,"instruction":"Pour a thin layer of batter, tilting to spread evenly like a crepe."},{"step":5,"instruction":"Cook one side only until set and flexible. Stack and serve with stew."}]'),

('Mullah', 'Sudan', 'Africa', true, 'Dinner', 'mullah-sudan',
'Thick Sudanese meat and vegetable stew with dried okra and peanut butter - the classic dinner topping for kisra.',
'Mullah is the generic Sudanese term for stew, with countless regional variations. It is always eaten with kisra, and the combination represents the heart of Sudanese home cooking.',
'Medium', 15, 45, 6, ARRAY['dinner', 'sudanese', 'stew', 'okra', 'peanut'],
'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=800&auto=format&fit=crop',
'[{"item":"Lamb or beef","quantity":"500g","note":"cubed"},{"item":"Dried okra powder","quantity":"3 tbsp"},{"item":"Peanut butter","quantity":"2 tbsp"},{"item":"Tomato paste","quantity":"2 tbsp"},{"item":"Onions","quantity":"2","note":"chopped"},{"item":"Garlic","quantity":"3 cloves"},{"item":"Vegetable oil","quantity":"3 tbsp"},{"item":"Salt","quantity":"to taste"},{"item":"Water","quantity":"3 cups"},{"item":"Kisra","quantity":"for serving"}]',
'[{"step":1,"instruction":"Brown meat in oil. Add onions and garlic, cook until soft."},{"step":2,"instruction":"Add tomato paste and cook 5 minutes."},{"step":3,"instruction":"Add water and simmer until meat is tender, about 30 minutes."},{"step":4,"instruction":"Mix dried okra powder and peanut butter with a little water. Add to stew."},{"step":5,"instruction":"Simmer 10 minutes until thick. Serve over kisra flatbread."}]'),

('Hilumur', 'Sudan', 'Africa', true, 'Drinks', 'hilumur-sudan',
'Sudanese spiced corn drink with ginger and citrus - a refreshing traditional beverage.',
'Hilumur is a traditional Sudanese refreshment made from corn and spices, typically served during Ramadan to break the fast. Its combination of sweet, tangy, and spicy flavors is unique.',
'Easy', 20, 15, 6, ARRAY['drinks', 'sudanese', 'corn', 'ginger', 'ramadan'],
'https://images.unsplash.com/photo-1550583724-b2692b85b150?w=800&auto=format&fit=crop',
'[{"item":"Corn flour","quantity":"1 cup"},{"item":"Fresh ginger","quantity":"2 inches","note":"grated"},{"item":"Cinnamon","quantity":"1 tsp"},{"item":"Cardamom","quantity":"1/2 tsp"},{"item":"Sugar","quantity":"1/2 cup"},{"item":"Lemon juice","quantity":"2 tbsp"},{"item":"Water","quantity":"4 cups"}]',
'[{"step":1,"instruction":"Toast corn flour lightly in a dry pan until fragrant."},{"step":2,"instruction":"Boil water with ginger, cinnamon, and cardamom for 5 minutes. Strain."},{"step":3,"instruction":"Mix toasted corn flour with cold water to make a paste."},{"step":4,"instruction":"Stir paste into spiced water. Cook 10 minutes until thick."},{"step":5,"instruction":"Add sugar and lemon juice. Cool completely. Serve chilled."}]'),

-- EGYPT
('Karkade', 'Egypt', 'Africa', true, 'Drinks', 'karkade-egypt',
'Egyptian hibiscus tea served both steaming hot in winter and ice cold in summer - a national staple beverage.',
'Karkade has been consumed in Egypt since the time of the Pharaohs. It is served at weddings (for its deep red color symbolizing love) and is a daily drink across the country.',
'Easy', 5, 10, 6, ARRAY['drinks', 'egyptian', 'hibiscus', 'tea', 'traditional'],
'https://images.unsplash.com/photo-1544145945-f90425340c7e?w=800&auto=format&fit=crop',
'[{"item":"Dried hibiscus flowers","quantity":"1 cup"},{"item":"Sugar","quantity":"1/2 cup"},{"item":"Water","quantity":"4 cups"},{"item":"Rose water","quantity":"1 tsp","note":"optional"},{"item":"Pine nuts","quantity":"for garnish"}]',
'[{"step":1,"instruction":"Wash hibiscus flowers well."},{"step":2,"instruction":"For hot: Steep flowers in boiling water for 10 minutes. Strain and sweeten."},{"step":3,"instruction":"For cold: Soak flowers in room temperature water overnight. Strain."},{"step":4,"instruction":"Add sugar and rose water if using."},{"step":5,"instruction":"Serve hot in winter or ice cold in summer. Garnish with pine nuts."}]'),

-- MOROCCO
('Msemen', 'Morocco', 'Africa', true, 'Breakfast', 'msemen-morocco',
'Flaky Moroccan square-shaped layered flatbread, crispy outside and soft inside - served with honey and butter for breakfast.',
'Msemen is one of Morocco''s most iconic breads, found in every bakery and home kitchen. The folding technique creates delicate layers reminiscent of a savory croissant.',
'Medium', 30, 20, 8, ARRAY['breakfast', 'moroccan', 'bread', 'flatbread', 'flaky'],
'https://images.unsplash.com/photo-1567364816519-cbc9c4a0a736?w=800&auto=format&fit=crop',
'[{"item":"All-purpose flour","quantity":"3 cups"},{"item":"Semolina","quantity":"1/2 cup"},{"item":"Salt","quantity":"1 tsp"},{"item":"Sugar","quantity":"1 tbsp"},{"item":"Warm water","quantity":"1.5 cups"},{"item":"Butter","quantity":"1/2 cup","note":"softened"},{"item":"Oil","quantity":"1/4 cup"},{"item":"Honey","quantity":"for serving"}]',
'[{"step":1,"instruction":"Mix flour, semolina, salt, and sugar. Add warm water and knead into a soft, smooth dough."},{"step":2,"instruction":"Rest 30 minutes. Divide into balls. Mix butter and oil for layering."},{"step":3,"instruction":"On an oiled surface, stretch each ball paper-thin. Brush with butter-oil mixture."},{"step":4,"instruction":"Fold into thirds, then thirds again to form a square. Rest 10 minutes."},{"step":5,"instruction":"Flatten and cook on a greased griddle until golden on both sides."},{"step":6,"instruction":"Serve warm with honey and butter or soft cheese."}]'),

('Moroccan Mint Tea', 'Morocco', 'Africa', true, 'Drinks', 'moroccan-mint-tea',
'Morocco''s iconic gunpowder green tea with fresh mint and sugar - poured from a height for a frothy finish.',
'Moroccan mint tea (Atay) is far more than a beverage - it is a symbol of friendship, hospitality, and tradition. The tea ceremony is central to social life, and refusing tea is considered impolite.',
'Easy', 5, 10, 4, ARRAY['drinks', 'moroccan', 'tea', 'mint', 'ceremony'],
'https://images.unsplash.com/photo-1571934811356-5cc061b6821f?w=800&auto=format&fit=crop',
'[{"item":"Chinese gunpowder green tea","quantity":"2 tbsp"},{"item":"Fresh mint","quantity":"1 large bunch"},{"item":"Sugar","quantity":"4-6 tbsp"},{"item":"Boiling water","quantity":"4 cups"}]',
'[{"step":1,"instruction":"Rinse tea leaves with a splash of boiling water to remove bitterness. Discard water."},{"step":2,"instruction":"Add tea to teapot with sugar and fresh mint. Pour boiling water."},{"step":3,"instruction":"Let steep 3-5 minutes."},{"step":4,"instruction":"Pour a glass, then pour it back into the pot. Repeat 2-3 times to mix."},{"step":5,"instruction":"Pour from a height into small glasses to create a frothy top. Serve hot."}]'),

('Pastilla', 'Morocco', 'Africa', true, 'Lunch', 'pastilla-morocco',
'Moroccan savory-sweet pie with shredded chicken, almonds, eggs, and cinnamon wrapped in warqa pastry.',
'Pastilla (or Bastilla) is Morocco''s most refined dish, originally made with pigeon. It was brought to Morocco by Andalusian refugees and represents the pinnacle of Moorish-Moroccan cuisine.',
'Hard', 60, 40, 8, ARRAY['lunch', 'moroccan', 'chicken', 'pastry', 'sweet-savory'],
'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=800&auto=format&fit=crop',
'[{"item":"Chicken","quantity":"1 whole","note":"cooked and shredded"},{"item":"Warqa or filo pastry","quantity":"12 sheets"},{"item":"Almonds","quantity":"1 cup","note":"toasted and ground"},{"item":"Eggs","quantity":"6","note":"scrambled in the broth"},{"item":"Onion","quantity":"2","note":"grated"},{"item":"Cinnamon","quantity":"2 tsp"},{"item":"Powdered sugar","quantity":"3 tbsp"},{"item":"Saffron","quantity":"pinch"},{"item":"Ginger","quantity":"1 tsp"},{"item":"Butter","quantity":"1/2 cup","note":"melted"},{"item":"Parsley and cilantro","quantity":"1/2 cup each"},{"item":"Salt and pepper","quantity":"to taste"}]',
'[{"step":1,"instruction":"Cook chicken in broth with onion, saffron, ginger, and herbs. Shred meat."},{"step":2,"instruction":"Reduce broth, add beaten eggs to make a thick custard-like mixture."},{"step":3,"instruction":"Mix ground almonds with cinnamon and sugar for the nut layer."},{"step":4,"instruction":"Layer buttered pastry in a pan. Add egg mixture, then chicken, then almond mixture."},{"step":5,"instruction":"Fold pastry over filling. Top with more buttered sheets. Bake at 375°F for 25 minutes until golden."},{"step":6,"instruction":"Dust with powdered sugar and cinnamon in a lattice pattern. Serve warm."}]'),

-- TUNISIA
('Lablabi', 'Tunisia', 'Africa', true, 'Breakfast', 'lablabi-tunisia',
'Tunisian hearty chickpea soup poured over torn bread with harissa, cumin, and olive oil - the ultimate winter breakfast.',
'Lablabi is Tunisia''s most popular street breakfast, especially during cold months. Workers line up at lablabi shops before dawn for this filling, affordable meal.',
'Easy', 10, 20, 4, ARRAY['breakfast', 'tunisian', 'chickpea', 'soup', 'harissa'],
'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=800&auto=format&fit=crop',
'[{"item":"Canned chickpeas","quantity":"2 cans","note":"with liquid"},{"item":"Stale bread","quantity":"4 slices","note":"torn"},{"item":"Harissa paste","quantity":"2 tbsp"},{"item":"Cumin","quantity":"2 tsp"},{"item":"Garlic","quantity":"3 cloves","note":"crushed"},{"item":"Olive oil","quantity":"4 tbsp"},{"item":"Lemon juice","quantity":"2 tbsp"},{"item":"Eggs","quantity":"4","note":"soft-boiled, optional"},{"item":"Capers","quantity":"2 tbsp"},{"item":"Salt","quantity":"to taste"}]',
'[{"step":1,"instruction":"Heat chickpeas with their liquid, crushed garlic, and cumin until simmering."},{"step":2,"instruction":"Place torn bread in bowls."},{"step":3,"instruction":"Ladle hot chickpea broth over the bread. Add a spoonful of harissa."},{"step":4,"instruction":"Drizzle generously with olive oil and lemon juice."},{"step":5,"instruction":"Top with capers and a halved soft-boiled egg. Serve immediately."}]'),

('Couscous au Poisson', 'Tunisia', 'Africa', true, 'Lunch', 'couscous-au-poisson-tunisia',
'Tunisian fish couscous with a spicy red sauce, potatoes, and seasonal vegetables - the Friday lunch tradition.',
'Fish couscous is the signature dish of Tunisia''s coastal cities like Sfax and Sousse. Unlike Moroccan couscous, the Tunisian version features a spicy, tomato-based broth.',
'Medium', 30, 50, 6, ARRAY['lunch', 'tunisian', 'fish', 'couscous', 'spicy'],
'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=800&auto=format&fit=crop',
'[{"item":"Couscous","quantity":"3 cups"},{"item":"Whole fish","quantity":"1 large","note":"cleaned"},{"item":"Tomato paste","quantity":"3 tbsp"},{"item":"Harissa","quantity":"2 tbsp"},{"item":"Potatoes","quantity":"2","note":"quartered"},{"item":"Zucchini","quantity":"2","note":"chunked"},{"item":"Carrots","quantity":"2","note":"chunked"},{"item":"Onion","quantity":"1","note":"diced"},{"item":"Olive oil","quantity":"3 tbsp"},{"item":"Caraway","quantity":"1 tsp"},{"item":"Salt","quantity":"to taste"},{"item":"Water","quantity":"4 cups"}]',
'[{"step":1,"instruction":"Sauté onion in olive oil. Add tomato paste, harissa, and caraway. Cook 3 minutes."},{"step":2,"instruction":"Add water, potatoes, and carrots. Simmer 15 minutes."},{"step":3,"instruction":"Add zucchini and cook 10 more minutes."},{"step":4,"instruction":"Add fish and cook 10-12 minutes until done."},{"step":5,"instruction":"Steam couscous separately until fluffy."},{"step":6,"instruction":"Serve couscous in a mound with vegetables and fish on top, broth on the side."}]'),

('Citronnade', 'Tunisia', 'Africa', true, 'Drinks', 'citronnade-tunisia',
'Tunisian fresh lemonade perfumed with orange blossom water and mint - elegantly refreshing.',
'Citronnade is Tunisia''s answer to lemonade, elevated with the signature North African touch of orange blossom water. It is the standard refreshment at cafés and restaurants.',
'Easy', 10, 0, 4, ARRAY['drinks', 'tunisian', 'lemon', 'orange-blossom', 'refreshing'],
'https://images.unsplash.com/photo-1513558161293-cdaf765ed2fd?w=800&auto=format&fit=crop',
'[{"item":"Lemons","quantity":"6","note":"juiced"},{"item":"Sugar","quantity":"1/2 cup"},{"item":"Orange blossom water","quantity":"1 tbsp"},{"item":"Fresh mint","quantity":"handful"},{"item":"Water","quantity":"4 cups"},{"item":"Ice","quantity":"plenty"}]',
'[{"step":1,"instruction":"Dissolve sugar in 1 cup warm water. Let cool."},{"step":2,"instruction":"Mix lemon juice, sugar syrup, orange blossom water, and remaining water."},{"step":3,"instruction":"Add mint leaves and stir."},{"step":4,"instruction":"Serve over plenty of ice in tall glasses."}]'),

-- ALGERIA
('Chakchouka', 'Algeria', 'Africa', true, 'Breakfast', 'chakchouka-algeria',
'Algerian eggs poached in a spicy tomato and pepper sauce with cumin and harissa - a hearty North African breakfast.',
'Chakchouka (or Shakshuka) has its roots in Algeria and Tunisia, long before becoming globally trendy. The Algerian version features merguez sausage and is spicier than its Middle Eastern cousins.',
'Easy', 10, 20, 4, ARRAY['breakfast', 'algerian', 'eggs', 'tomato', 'spicy'],
'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=800&auto=format&fit=crop',
'[{"item":"Eggs","quantity":"6"},{"item":"Tomatoes","quantity":"6","note":"diced"},{"item":"Bell peppers","quantity":"2","note":"diced"},{"item":"Onion","quantity":"1","note":"diced"},{"item":"Garlic","quantity":"3 cloves"},{"item":"Harissa","quantity":"1 tbsp"},{"item":"Cumin","quantity":"1 tsp"},{"item":"Paprika","quantity":"1 tsp"},{"item":"Olive oil","quantity":"3 tbsp"},{"item":"Salt","quantity":"to taste"},{"item":"Bread","quantity":"for serving"}]',
'[{"step":1,"instruction":"Sauté onion and peppers in olive oil until soft."},{"step":2,"instruction":"Add garlic, cumin, paprika, and harissa. Cook 1 minute."},{"step":3,"instruction":"Add tomatoes and salt. Simmer 10-15 minutes until thick."},{"step":4,"instruction":"Make wells in the sauce. Crack eggs into wells."},{"step":5,"instruction":"Cover and cook 5-7 minutes until whites are set but yolks are runny."},{"step":6,"instruction":"Serve in the pan with crusty bread for dipping."}]'),

('Rechta', 'Algeria', 'Africa', true, 'Lunch', 'rechta-algeria',
'Algerian handmade thin pasta in a cinnamon-spiced chicken and chickpea sauce - a celebration lunch dish.',
'Rechta is Algeria''s most prestigious dish, served at weddings and celebrations. The hand-rolling of the pasta is an art form passed down through generations of Algerian women.',
'Hard', 60, 40, 8, ARRAY['lunch', 'algerian', 'pasta', 'chicken', 'cinnamon'],
'https://images.unsplash.com/photo-1504674900247-0877df9cc836?w=800&auto=format&fit=crop',
'[{"item":"Flour","quantity":"3 cups","note":"for pasta"},{"item":"Salt","quantity":"1 tsp"},{"item":"Water","quantity":"1 cup"},{"item":"Chicken","quantity":"1 whole","note":"cut into pieces"},{"item":"Chickpeas","quantity":"1 cup","note":"soaked"},{"item":"Turnips","quantity":"2","note":"quartered"},{"item":"Onion","quantity":"2","note":"grated"},{"item":"Cinnamon sticks","quantity":"2"},{"item":"Butter","quantity":"4 tbsp"},{"item":"Salt and pepper","quantity":"to taste"}]',
'[{"step":1,"instruction":"Make pasta: Mix flour, salt, and water. Knead into firm dough. Roll paper-thin and cut into thin noodles."},{"step":2,"instruction":"Cook chicken with onion, cinnamon, chickpeas, and water until tender."},{"step":3,"instruction":"Add turnips and cook until soft. Remove cinnamon sticks."},{"step":4,"instruction":"Steam the noodles until tender. Toss with butter."},{"step":5,"instruction":"Serve noodles in a mound, topped with chicken and vegetables, broth ladled over."}]'),

('Algerian Lemonade', 'Algeria', 'Africa', true, 'Drinks', 'algerian-lemonade',
'Refreshing Algerian citrus drink with lemon verbena and orange peel - the summertime staple.',
'Algerian lemonade reflects the country''s abundant citrus orchards, particularly in the Mitidja plain. It is the standard refreshment during hot summers.',
'Easy', 10, 0, 4, ARRAY['drinks', 'algerian', 'lemon', 'citrus', 'refreshing'],
'https://images.unsplash.com/photo-1513558161293-cdaf765ed2fd?w=800&auto=format&fit=crop',
'[{"item":"Lemons","quantity":"5","note":"juiced"},{"item":"Orange","quantity":"1","note":"juiced"},{"item":"Sugar","quantity":"1/2 cup"},{"item":"Lemon verbena leaves","quantity":"6"},{"item":"Water","quantity":"1 liter"},{"item":"Ice","quantity":"plenty"}]',
'[{"step":1,"instruction":"Make a simple syrup with sugar and a little water. Add lemon verbena while warm."},{"step":2,"instruction":"Let cool and strain out leaves."},{"step":3,"instruction":"Mix lemon juice, orange juice, verbena syrup, and water."},{"step":4,"instruction":"Serve over ice in tall glasses."}]'),

-- LIBYA
('Bazeen', 'Libya', 'Africa', true, 'Dinner', 'bazeen-libya',
'Libyan dome-shaped barley dough served with a rich lamb, tomato, and turmeric stew - the national dinner.',
'Bazeen is Libya''s most iconic dish, traditionally eaten communally from a large platter. The firm dough dome is surrounded by a flavorful stew, and eaten by pinching off pieces.',
