'https://images.unsplash.com/photo-1574484284002-952d92456975?w=800&auto=format&fit=crop',
'[{"item":"Barley flour","quantity":"3 cups"},{"item":"Water","quantity":"for dough"},{"item":"Lamb","quantity":"500g","note":"on the bone"},{"item":"Tomato paste","quantity":"3 tbsp"},{"item":"Turmeric","quantity":"1 tsp"},{"item":"Onion","quantity":"1","note":"chopped"},{"item":"Potatoes","quantity":"2","note":"quartered"},{"item":"Eggs","quantity":"3","note":"boiled"},{"item":"Chili peppers","quantity":"2"},{"item":"Salt","quantity":"to taste"}]',
'[{"step":1,"instruction":"Cook lamb with onion, tomato paste, turmeric, and salt until tender, about 45 minutes."},{"step":2,"instruction":"Add potatoes and boiled eggs to the stew. Cook 15 more minutes."},{"step":3,"instruction":"For bazeen: Boil water, add barley flour gradually while stirring vigorously."},{"step":4,"instruction":"Cook and stir until very thick and forms a smooth dough ball."},{"step":5,"instruction":"Place bazeen dome in center of a large platter. Surround with stew, meat, eggs, and potatoes."},{"step":6,"instruction":"Eat communally by pinching off dough and dipping in sauce."}]'),

('Asida', 'Libya', 'Africa', true, 'Breakfast', 'asida-libya',
'Libyan smooth wheat porridge served with date syrup or honey - a comforting celebration breakfast.',
'Asida is traditionally prepared to celebrate births and religious occasions. The simplicity of the dish belies its cultural significance in Libyan family life.',
'Easy', 5, 15, 4, ARRAY['breakfast', 'libyan', 'wheat', 'porridge', 'celebration'],
'https://images.unsplash.com/photo-1517673400267-0251440c45dc?w=800&auto=format&fit=crop',
'[{"item":"Wheat flour","quantity":"2 cups"},{"item":"Water","quantity":"4 cups"},{"item":"Salt","quantity":"1/2 tsp"},{"item":"Butter","quantity":"3 tbsp"},{"item":"Date syrup (rub)","quantity":"for serving"},{"item":"Honey","quantity":"for serving"}]',
'[{"step":1,"instruction":"Bring salted water to a boil."},{"step":2,"instruction":"Gradually add flour while stirring vigorously with a wooden spoon."},{"step":3,"instruction":"Cook for 10 minutes, stirring constantly until thick and smooth."},{"step":4,"instruction":"Shape into a dome on a plate. Make a well in the center."},{"step":5,"instruction":"Fill well with butter and drizzle date syrup over. Serve warm."}]'),

-- ERITREA
('Shahan Ful', 'Eritrea', 'Africa', true, 'Breakfast', 'shahan-ful-eritrea',
'Eritrean mashed fava beans with tomato, cumin, and chili oil - the quintessential Horn of Africa breakfast.',
'Shahan Ful is the morning fuel of Eritrea, served at every café and street stall. It connects Eritrean food culture to the broader Horn of Africa tradition of fava bean dishes.',
'Easy', 10, 15, 4, ARRAY['breakfast', 'eritrean', 'fava-beans', 'cumin', 'protein'],
'https://images.unsplash.com/photo-1512058564366-18510be2db19?w=800&auto=format&fit=crop',
'[{"item":"Canned fava beans","quantity":"2 cans"},{"item":"Tomato","quantity":"2","note":"diced"},{"item":"Onion","quantity":"1","note":"diced"},{"item":"Cumin","quantity":"1 tsp"},{"item":"Chili flakes","quantity":"1/2 tsp"},{"item":"Olive oil","quantity":"3 tbsp"},{"item":"Lemon juice","quantity":"1 tbsp"},{"item":"Salt","quantity":"to taste"},{"item":"Bread","quantity":"for serving"}]',
'[{"step":1,"instruction":"Heat fava beans in a pot, mashing lightly with a fork."},{"step":2,"instruction":"Add cumin, chili flakes, and salt. Cook 5 minutes."},{"step":3,"instruction":"Serve in a bowl. Top with diced tomato and onion."},{"step":4,"instruction":"Drizzle generously with olive oil and lemon juice."},{"step":5,"instruction":"Eat with bread, scooping up the beans."}]'),

('Suwa', 'Eritrea', 'Africa', true, 'Drinks', 'suwa-eritrea',
'Eritrean traditional homebrew beer made from roasted barley and gesho - an ancient grain beer.',
'Suwa is Eritrea''s traditional beer, brewed in homes for celebrations and daily consumption. The brewing process, using gesho (a native hop-like plant), connects to ancient East African brewing traditions.',
'Medium', 60, 0, 8, ARRAY['drinks', 'eritrean', 'beer', 'traditional', 'fermented'],
'https://images.unsplash.com/photo-1513558161293-cdaf765ed2fd?w=800&auto=format&fit=crop',
'[{"item":"Barley","quantity":"2 kg","note":"roasted until dark"},{"item":"Gesho leaves","quantity":"1 cup"},{"item":"Water","quantity":"5 liters"},{"item":"Wheat flour","quantity":"1/2 cup","note":"toasted"}]',
'[{"step":1,"instruction":"Roast barley until very dark. Grind coarsely."},{"step":2,"instruction":"Mix with toasted wheat flour and gesho leaves. Add warm water."},{"step":3,"instruction":"Cover and ferment for 4-5 days, stirring daily."},{"step":4,"instruction":"Strain through cloth when desired strength is reached."},{"step":5,"instruction":"Serve in traditional clay cups. Suwa should be slightly thick and earthy."}]'),

-- DJIBOUTI
('Fah-Fah', 'Djibouti', 'Africa', true, 'Dinner', 'fah-fah-djibouti',
'Djiboutian hearty lamb soup with vegetables and spices - the national comfort dinner.',
'Fah-Fah is Djibouti''s signature soup, reflecting the nomadic Afar and Somali culinary traditions. It is particularly popular during Ramadan for breaking the fast.',
'Easy', 15, 45, 6, ARRAY['dinner', 'djiboutian', 'lamb', 'soup', 'ramadan'],
'https://images.unsplash.com/photo-1547592166-23ac45744acd?w=800&auto=format&fit=crop',
'[{"item":"Lamb","quantity":"500g","note":"with bones"},{"item":"Potatoes","quantity":"2","note":"cubed"},{"item":"Carrots","quantity":"2","note":"sliced"},{"item":"Onion","quantity":"1","note":"chopped"},{"item":"Tomato","quantity":"2","note":"diced"},{"item":"Garlic","quantity":"3 cloves"},{"item":"Cumin","quantity":"1 tsp"},{"item":"Coriander","quantity":"1 tsp"},{"item":"Chili","quantity":"1"},{"item":"Salt","quantity":"to taste"},{"item":"Water","quantity":"6 cups"}]',
'[{"step":1,"instruction":"Boil lamb with onion, garlic, and spices until tender, about 30 minutes."},{"step":2,"instruction":"Add potatoes, carrots, and tomatoes. Cook 15 minutes."},{"step":3,"instruction":"Season with salt. The broth should be rich and slightly spicy."},{"step":4,"instruction":"Serve hot in bowls with bread for dipping."}]'),

('Laxoox', 'Djibouti', 'Africa', true, 'Breakfast', 'laxoox-djibouti',
'Djiboutian spongy fermented pancake served with honey and butter - the breakfast of the Horn of Africa.',
'Laxoox is the daily bread of Djibouti, similar to Somali canjeero. It is eaten at breakfast with tea, and throughout the day with stews.',
'Easy', 480, 15, 4, ARRAY['breakfast', 'djiboutian', 'fermented', 'pancake', 'spongy'],
'https://images.unsplash.com/photo-1567364816519-cbc9c4a0a736?w=800&auto=format&fit=crop',
'[{"item":"All-purpose flour","quantity":"2 cups"},{"item":"Cornmeal","quantity":"1/2 cup"},{"item":"Yeast","quantity":"1 tsp"},{"item":"Sugar","quantity":"1 tbsp"},{"item":"Water","quantity":"2.5 cups"},{"item":"Butter and honey","quantity":"for serving"}]',
'[{"step":1,"instruction":"Mix flour, cornmeal, yeast, and sugar. Add warm water and mix until smooth."},{"step":2,"instruction":"Cover and ferment 6-8 hours until bubbly."},{"step":3,"instruction":"Heat a non-stick pan. Pour thin batter to cover the surface."},{"step":4,"instruction":"Cook one side only until set with small holes on the surface."},{"step":5,"instruction":"Spread with butter and drizzle with honey. Fold and serve with tea."}]'),

-- SOUTH SUDAN
('Kisra with Mulah', 'South Sudan', 'Africa', true, 'Dinner', 'kisra-mulah-south-sudan',
'South Sudanese sorghum flatbread with thick peanut and okra meat stew - the national dinner.',
'This combination of kisra and mulah represents the culinary identity of South Sudan, the world''s youngest country. It connects to the broader Sudanese tradition while having distinct southern flavors.',
'Medium', 30, 45, 6, ARRAY['dinner', 'south-sudanese', 'sorghum', 'peanut', 'stew'],
'https://images.unsplash.com/photo-1574484284002-952d92456975?w=800&auto=format&fit=crop',
'[{"item":"Sorghum flour","quantity":"2 cups"},{"item":"Water","quantity":"for batter"},{"item":"Beef","quantity":"500g","note":"cubed"},{"item":"Peanut butter","quantity":"3 tbsp"},{"item":"Okra","quantity":"200g","note":"sliced"},{"item":"Tomatoes","quantity":"3","note":"diced"},{"item":"Onion","quantity":"1","note":"chopped"},{"item":"Dried fish","quantity":"100g"},{"item":"Salt","quantity":"to taste"}]',
'[{"step":1,"instruction":"Make kisra: Mix sorghum flour with water to a thin batter. Let ferment overnight."},{"step":2,"instruction":"Cook thin pancakes one side only on a hot griddle. Stack and cover."},{"step":3,"instruction":"For mulah: Cook beef with onions until tender."},{"step":4,"instruction":"Add tomatoes, dried fish, and peanut butter dissolved in water."},{"step":5,"instruction":"Add okra and simmer 20 minutes until thick. Serve stew over kisra."}]'),

('Walwal', 'South Sudan', 'Africa', true, 'Drinks', 'walwal-south-sudan',
'South Sudanese traditional sorghum beer - a milky, tangy fermented beverage for celebrations.',
'Walwal is brewed for important social occasions in South Sudan, including weddings, funerals, and community gatherings. It represents communal bonds and hospitality.',
'Medium', 60, 0, 8, ARRAY['drinks', 'south-sudanese', 'sorghum', 'beer', 'traditional'],
