'[{"item":"Sorghum grain","quantity":"2 kg"},{"item":"Water","quantity":"5 liters"},{"item":"Sorghum malt","quantity":"500g"}]',
'[{"step":1,"instruction":"Soak sorghum grain in water for 24 hours. Drain."},{"step":2,"instruction":"Spread on a mat to germinate for 3 days, keeping moist."},{"step":3,"instruction":"Dry and grind the malted grain. Mix with water and cook into a porridge."},{"step":4,"instruction":"Cool and add sorghum malt as a fermenting agent."},{"step":5,"instruction":"Ferment for 2-3 days. Strain and serve in calabash gourds."}]')

